body:
// ---------------- helper registers ----------------
logic                     rst_q = 1'b0;
logic                     a_valid_q = 1'b0;
logic                     pend = 1'b0;
logic                     pend_rd = 1'b0;
logic                     ls_q = 1'b0;      // legal setup edge registered
logic                     il_q = 1'b0;      // illegal setup edge registered
logic                     pw_q = 1'b0;
logic [(PARA_ADDR_W)-1:0] pa_q = '0;
logic [31:0]              pd_q = '0;
logic                     resp_q = 1'b0;
logic                     rd_q = 1'b0;
logic                     err_q = 1'b0;
logic [31:0]              rdat_q = '0;
logic                     have_rise = 1'b0;
logic [1:0]               acc_cnt = 2'd0;
logic                     prdy_seen = 1'b0;

wire setup_w   = i_apb_psel && !i_apb_penable;
wire legal_w   = setup_w && (i_apb_paddr[1:0] == 2'b00) && (!i_apb_pwrite || (i_apb_pstrb == 4'b1111));
wire illegal_w = setup_w && ((i_apb_paddr[1:0] != 2'b00) || (i_apb_pwrite && (i_apb_pstrb != 4'b1111)));
wire acc_w     = o_tlul_a_valid && i_tlul_a_ready;
wire resp_w    = i_tlul_d_valid && o_tlul_d_ready && (acc_w || pend);
wire rd_w      = pend ? pend_rd : o_tlul_a_opcode[2];
wire err_w     = i_tlul_d_error
               | (i_tlul_d_opcode != (rd_w ? 3'b001 : 3'b000))
               | (i_tlul_d_source != PARA_SRC_ID[PARA_SRC_W-1:0]);
wire rise_w    = rst_q && o_tlul_a_valid && !a_valid_q;

always_ff @(posedge i_clk_core) begin
  rst_q     <= i_rst_n_core;
  a_valid_q <= o_tlul_a_valid;
  ls_q      <= i_rst_n_core && legal_w;
  il_q      <= i_rst_n_core && illegal_w;
  pw_q      <= i_apb_pwrite;
  pa_q      <= i_apb_paddr;
  pd_q      <= i_apb_pwdata;
  resp_q    <= i_rst_n_core && resp_w;
  rd_q      <= rd_w;
  err_q     <= err_w;
  rdat_q    <= i_tlul_d_data;
  if (!i_rst_n_core) begin
    pend      <= 1'b0;
    pend_rd   <= 1'b0;
    have_rise <= 1'b0;
    acc_cnt   <= 2'd0;
    prdy_seen <= 1'b0;
  end else begin
    pend <= (acc_w | pend) & ~resp_w;
    if (acc_w) pend_rd <= o_tlul_a_opcode[2];
    if (rise_w) begin
      have_rise <= 1'b1;
      acc_cnt   <= acc_w ? 2'd1 : 2'd0;
      prdy_seen <= 1'b0;
    end else begin
      if (acc_w && acc_cnt != 2'd3) acc_cnt <= acc_cnt + 2'd1;
      if (o_apb_pready) prdy_seen <= 1'b1;
    end
  end
end

// CHK-005: Both sides idle in the Setup cycle (BR-10.3-03, BR-5.4-06, BR-5.3-11)
a_CHK_005: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  (i_apb_psel && !i_apb_penable) |-> (!o_apb_pready && !o_tlul_a_valid))
  else begin fails_CHK_005++; $display("NNC_FAIL CHK-005 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (i_apb_psel && !i_apb_penable)) hits_CHK_005 <= hits_CHK_005 + 1;

// CHK-006: A TL-UL request starts only after a legal Setup (BR-5.4-02, BR-5.4-05, BR-15.3-07, BR-T1-05, BR-12-02, BR-20-05, BR-1.1-01)
a_CHK_006: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  (rst_q && !a_valid_q && o_tlul_a_valid) |-> ls_q)
  else begin fails_CHK_006++; $display("NNC_FAIL CHK-006 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (rst_q && !a_valid_q && o_tlul_a_valid)) hits_CHK_006 <= hits_CHK_006 + 1;

// CHK-007: Early launch of a legal request in the first Access cycle (BR-1.1-02, BR-1.3-01, BR-1.3-02, BR-3-01, BR-3-02, BR-3-03, BR-3-04, BR-3-12, BR-5.1-02, BR-5.3-01, BR-5.3-02, BR-5.3-04, BR-6.2-06, BR-6.2-07, BR-6.2-13, BR-6.3-10, BR-6.3-12, BR-9-03, BR-9-05, BR-10.1-01, BR-15.3-08, BR-15.3-10, BR-20-12)
a_CHK_007: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  ls_q |-> (o_tlul_a_valid
            && (o_tlul_a_opcode == (pw_q ? 3'b000 : 3'b100))
            && (o_tlul_a_address == pa_q)
            && (!pw_q || (o_tlul_a_data == pd_q))
            && o_tlul_d_ready && !o_apb_pready))
  else begin fails_CHK_007++; $display("NNC_FAIL CHK-007 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (ls_q)) hits_CHK_007 <= hits_CHK_007 + 1;

// CHK-008: Local error completion for an illegal request (BR-T1-03, BR-T1-04, BR-T1-05, BR-1.3-03, BR-2.3-01, BR-2.3-02, BR-3-10, BR-3-24, BR-3-25, BR-3-36, BR-5.4-05, BR-6.3-11, BR-6.3-13, BR-9-04, BR-9-10, BR-10.1-02, BR-10.3-01, BR-12-01, BR-12-02, BR-12-04, BR-15.3-07, BR-15.3-10, BR-20-05)
a_CHK_008: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  il_q |-> (o_apb_pready && o_apb_pslverr && (o_apb_prdata == 32'h0) && !o_tlul_a_valid))
  else begin fails_CHK_008++; $display("NNC_FAIL CHK-008 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (il_q)) hits_CHK_008 <= hits_CHK_008 + 1;

// CHK-009: Accepted TL-UL response is mapped to the APB completion in the next cycle (BR-1.1-01, BR-1.3-04, BR-3-09, BR-3-10, BR-3-26, BR-3-27, BR-3-28, BR-5.1-03, BR-5.3-06, BR-5.3-07, BR-5.3-08, BR-6.3-14, BR-6.3-15, BR-8-04, BR-8-08, BR-9-09, BR-9-10, BR-10.1-03, BR-10.1-05, BR-12-05, BR-12-07, BR-20-10)
a_CHK_009: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  resp_q |-> (o_apb_pready && (o_apb_pslverr == err_q)
              && (o_apb_prdata == ((rd_q && !err_q) ? rdat_q : 32'h0))))
  else begin fails_CHK_009++; $display("NNC_FAIL CHK-009 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (resp_q)) hits_CHK_009 <= hits_CHK_009 + 1;

// CHK-010: PREADY only as the result of a request; orphan responses have no APB effect (BR-3-11, BR-3-18, BR-6.2-03, BR-6.3-08, BR-10.1-06, BR-12-09, BR-15.3-09)
a_CHK_010: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  (rst_q && o_apb_pready) |-> (il_q || resp_q))
  else begin fails_CHK_010++; $display("NNC_FAIL CHK-010 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (rst_q && o_apb_pready)) hits_CHK_010 <= hits_CHK_010 + 1;

// CHK-011: At most one TL-UL request outstanding, none before the APB completion (BR-3-06, BR-3-07, BR-5.4-01, BR-6.3-06, BR-15.3-03, BR-1.1-04)
a_CHK_011: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  (have_rise && rise_w) |-> ((acc_cnt == 2'd1) && prdy_seen))
  else begin fails_CHK_011++; $display("NNC_FAIL CHK-011 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (have_rise && rise_w)) hits_CHK_011 <= hits_CHK_011 + 1;
